<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('lab.php');$page_title='Laboratorium';$page_subtitle=is_role('laboratory')?'LIS worklist: specimen/order processing and verification of results.':'Hasil laboratorium read-only untuk clinical decision making.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&is_role('laboratory')){check_csrf();$oid=(int)$_POST['order_id'];$s=$pdo->prepare("SELECT id FROM cpoe_orders WHERE id=? AND order_type='laboratory'");$s->execute([$oid]);if(!$s->fetchColumn())$msg='Order laboratorium tidak ditemukan.';else{$q=$pdo->prepare('SELECT id FROM lab_results WHERE order_id=? LIMIT 1');$q->execute([$oid]);$rid=$q->fetchColumn();if($rid){$q=$pdo->prepare('UPDATE lab_results SET test_name=?,result_value=?,unit=?,reference_range=?,flag=?,verified_by=?,result_notes=?,reported_at=NOW() WHERE id=?');$q->execute([trim($_POST['test_name']),trim($_POST['result_value']),trim($_POST['unit']),trim($_POST['reference_range']),$_POST['flag'],current_user_id(),trim($_POST['result_notes']),$rid]);}else{$q=$pdo->prepare('INSERT INTO lab_results(order_id,test_name,result_value,unit,reference_range,flag,verified_by,result_notes,reported_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$q->execute([$oid,trim($_POST['test_name']),trim($_POST['result_value']),trim($_POST['unit']),trim($_POST['reference_range']),$_POST['flag'],current_user_id(),trim($_POST['result_notes'])]);}$pdo->prepare("UPDATE cpoe_orders SET status='completed',completed_at=NOW() WHERE id=?")->execute([$oid]);audit($pdo,'VERIFY','LAB_RESULT',$oid,'Hasil laboratorium diverifikasi dan dirilis.');$msg='Hasil laboratorium berhasil diverifikasi.';}}
$where="WHERE o.order_type='laboratory'";$params=[];if(is_role('patient')){$where.=' AND o.patient_id=?';$params[] = current_patient_id($pdo)??0;}elseif(is_role('doctor')){$where.=' AND EXISTS(SELECT 1 FROM encounters e WHERE e.id=o.encounter_id AND e.doctor_id=?)';$params[]=doctor_id($pdo);}elseif(is_role('nurse')){$where.=' AND EXISTS(SELECT 1 FROM vital_signs v WHERE v.patient_id=o.patient_id AND v.recorded_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR))';}
$sql="SELECT o.*,p.name patient,p.mrn,lr.id result_id,lr.test_name,lr.result_value,lr.unit,lr.reference_range,lr.flag,lr.result_notes,lr.reported_at FROM cpoe_orders o JOIN patients p ON p.id=o.patient_id LEFT JOIN lab_results lr ON lr.order_id=o.id $where ORDER BY o.ordered_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();include __DIR__.'/includes/header.php';?><?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?><div class="grid two"><div class="card"><div class="card-header"><div><h3 class="section-title">Laboratory Worklist</h3><p class="section-subtitle"><?=count($orders)?> order dalam scope.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Exam</th><th>Priority</th><th>Status</th><th>Result</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['patient'])?><br><span class="mini"><?=h($o['mrn'])?></span></td><td><?=h($o['order_name'])?></td><td><?=h(strtoupper($o['priority']))?></td><td><?=h($o['status'])?></td><td><?=h($o['result_value']?:'Pending')?></td></tr><?php endforeach;?></table></div></div><div class="card"><?php if(is_role('laboratory')):?><div class="card-header"><div><h3 class="section-title">Verify Result</h3><p class="section-subtitle">Final release dilakukan petugas laboratorium.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Order</label><select name="order_id" required><?php foreach($orders as $o):?><option value="<?=$o['id']?>">#<?=$o['id']?> — <?=h($o['patient'].' · '.$o['order_name'])?></option><?php endforeach;?></select><br><label>Test Name</label><input name="test_name" required placeholder="Hemoglobin"><br><label>Result Value</label><input name="result_value" required placeholder="13.5"><br><div class="form-grid"><div><label>Unit</label><input name="unit" placeholder="g/dL"></div><div><label>Reference Range</label><input name="reference_range" placeholder="12–16"></div></div><br><label>Flag</label><select name="flag"><option value="normal">Normal</option><option value="low">Low</option><option value="high">High</option><option value="critical">Critical</option></select><br><label>Result Notes</label><textarea name="result_notes"></textarea><button class="btn primary" style="margin-top:10px">✓ Verify & Release</button></form><?php else:?><div class="notice"><div>🔬</div><div><strong>Read-only result viewer</strong><span>Dokter, perawat, Rekam Medis, dan pasien tidak dapat mengubah hasil laboratorium.</span></div></div><?php endif;?></div></div><?php include __DIR__.'/includes/footer.php';?>